package api

import "testing"

func TestTicketCreationRejectedWhenAgentAtCapacity(t *testing.T) {
	srv := startServer(t)
	defer srv.Close()

	cap := 1
	agent := doRequest(t, srv.URL, "POST", "/api/agents", map[string]any{
		"name": "Ada", "email": "a@example.com", "maxOpenTickets": cap,
	})
	agentID := agent.body["id"]

	first := doRequest(t, srv.URL, "POST", "/api/tickets", map[string]any{"subject": "A", "agentId": agentID})
	if first.status != 201 {
		t.Fatalf("expected 201, got %d", first.status)
	}

	second := doRequest(t, srv.URL, "POST", "/api/tickets", map[string]any{"subject": "B", "agentId": agentID})
	if second.status != 400 {
		t.Fatalf("expected 400 (agent at capacity 1), got %d", second.status)
	}
}

func TestTicketReassignmentRejectedWhenAgentAtCapacity(t *testing.T) {
	srv := startServer(t)
	defer srv.Close()

	cap := 1
	agent := doRequest(t, srv.URL, "POST", "/api/agents", map[string]any{
		"name": "Ada", "email": "a@example.com", "maxOpenTickets": cap,
	})
	agentID := agent.body["id"]

	doRequest(t, srv.URL, "POST", "/api/tickets", map[string]any{"subject": "A", "agentId": agentID})
	unassigned := doRequest(t, srv.URL, "POST", "/api/tickets", map[string]any{"subject": "B"})
	unassignedID := jsonNum(unassigned.body["id"])

	reassign := doRequest(t, srv.URL, "PATCH", "/api/tickets/"+unassignedID, map[string]any{"agentId": agentID})
	if reassign.status != 400 {
		t.Fatalf("expected 400 - reassignment must respect the cap too, got %d", reassign.status)
	}
}

